public struct FfiConverterTypeSshSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SshSession

    public static func lift(_ handle: UInt64) throws -> SshSession {
        return SshSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SshSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SshSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SshSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSshSession_lift(_ handle: UInt64) throws -> SshSession {
    return try FfiConverterTypeSshSession.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSshSession_lower(_ value: SshSession) -> UInt64 {
    return FfiConverterTypeSshSession.lower(value)
}






public protocol TakoCoreProtocol: AnyObject, Sendable {

    /**
     * Export the terminal state as a native versioned binary checkpoint.
     */
    func checkpoint()  -> Data

    /**
     * Export bounded by a caller-supplied byte cap.
     */
